<?php
declare(strict_types=1);
const APP_NAME='EZShift';
function db(): ?PDO { static $pdo=null; if($pdo instanceof PDO)return $pdo; $host=getenv('EZSHIFT_DB_HOST')?:'127.0.0.1';$name=getenv('EZSHIFT_DB_NAME')?:'ezshift_db';$user=getenv('EZSHIFT_DB_USER')?:'root';$pass=getenv('EZSHIFT_DB_PASS')?:''; try{$pdo=new PDO("mysql:host=$host;dbname=$name;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $pdo;}catch(Throwable $x){return null;} }
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function current_user():?array{return $_SESSION['user']??null;}
function flash(string $msg,string $type='success'):void{$_SESSION['flash']=['msg'=>$msg,'type'=>$type];}
function take_flash():?array{$f=$_SESSION['flash']??null;unset($_SESSION['flash']);return $f;}
function go(string $page):never{header('Location: index.php?page='.urlencode($page));exit;}
function require_role(string $role):void{if(!current_user()){flash('Please sign in to continue.','error');go('login');}if(current_user()['role']!==$role){flash('You do not have access to that page.','error');go('home');}}
function handle_post():void{
 $action=$_POST['action']??'';$pdo=db();
 if($action==='register'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$password=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||$password!==($_POST['confirm']??'')){flash('Enter your name, valid email, matching passwords, and a password with at least 8 characters.','error');go('register');}if(!$pdo){flash('Database is not connected. Import database/ezshift.sql and update includes/app.php settings.','error');go('register');}try{$q=$pdo->prepare("INSERT INTO users(name,email,phone,address,password_hash,role) VALUES(?,?,?,?,?,'customer')");$q->execute([$name,$email,$phone,$address,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];flash('Your EZShift account is ready.');go('dashboard');}catch(Throwable $x){flash('That email is already registered. Please sign in instead.','error');go('register');}}
 if($action==='login'){if(!$pdo){flash('Database is not connected. Import database/ezshift.sql first.','error');go('login');}$q=$pdo->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=? AND active=1 LIMIT 1');$q->execute([strtolower(trim($_POST['email']??''))]);$u=$q->fetch();if($u&&$u['role']==='customer'&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>'customer'];go('dashboard');}if($u&&$u['role']==='admin'){flash('Use the dedicated administrator sign-in.','error');}else{flash('Email or password was not recognized.','error');}go('login');}if($action==='admin-login'){if(!$pdo){flash('Database is not connected. Import database/ezshift.sql first.','error');go('admin-login');}$q=$pdo->prepare("SELECT id,name,email,password_hash FROM users WHERE email=? AND role='admin' AND active=1 LIMIT 1");$q->execute([strtolower(trim($_POST['email']??''))]);$u=$q->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>'admin'];go('admin');}flash('Administrator email or password was not recognized.','error');go('admin-login');}
 if($action==='logout'){session_destroy();header('Location: index.php');exit;}
 if($action==='contact'){if($pdo){$q=$pdo->prepare('INSERT INTO contact_messages(name,email,phone,subject,message) VALUES(?,?,?,?,?)');$q->execute([trim($_POST['name']??''),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['subject']??''),trim($_POST['message']??'')]);}flash('Thanks for reaching out. Our moving team will be in touch shortly.');go('contact');}
 if($action==='booking'){require_role('customer');$data=booking_input();if(!$data){flash('Please complete the required booking details.','error');go('book');}if(!$pdo){flash('Database is not connected. Import database/ezshift.sql first.','error');go('book');}$estimate=estimate($data);$id='EZ-'.date('Y').'-'.str_pad((string)random_int(1,99999),5,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO bookings(booking_code,user_id,move_type,pickup_address,pickup_city,destination_address,destination_city,move_date,move_time,vehicle_id,workers,notes,estimated_total,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,\'Pending\')');$q->execute([$id,current_user()['id'],$data['type'],$data['pickup'],$data['pcity'],$data['destination'],$data['dcity'],$data['date'],$data['time'],$data['vehicle'],$data['workers'],$data['notes'],$estimate]);$bid=(int)$pdo->lastInsertId();foreach($data['items'] as $item){$qi=$pdo->prepare('INSERT INTO booking_items(booking_id,item_name,quantity,weight,special) VALUES(?,?,?,?,?)');$qi->execute([$bid,$item['name'],$item['qty'],$item['weight'],$item['special']]);}foreach($data['services'] as $sid){$q=$pdo->prepare('INSERT INTO booking_services(booking_id,service_id) VALUES(?,?)');$q->execute([$bid,(int)$sid]);}flash('Move request received. We’ll review the details and confirm your booking.');header('Location: index.php?page=booking&id='.$bid);exit;}
 if($action==='update-status'){require_role('admin');$allowed=['Pending','Confirmed','Workers Assigned','Vehicle Assigned','On the Way','Loading','In Transit','Unloading','Completed','Cancelled'];$status=$_POST['status']??'';if(!in_array($status,$allowed,true)){flash('Choose a valid booking status.','error');go('admin-bookings');}if($pdo){$q=$pdo->prepare('UPDATE bookings SET status=?,updated_at=NOW() WHERE id=?');$q->execute([$status,(int)($_POST['booking_id']??0)]);}flash('Booking status updated.');$returnTo=$_POST['return_to']??'admin-bookings';go(in_array($returnTo,['admin','admin-bookings'],true)?$returnTo:'admin-bookings');}
 if($action==='add-vehicle'){require_role('admin');if(!$pdo){flash('Database is not connected.','error');go('admin-vehicles');}$name=trim($_POST['name']??'');$plate=trim($_POST['vehicle_number']??'');$model=trim($_POST['model']??'');$capacity=trim($_POST['capacity']??'');$base=max(0,(float)($_POST['base_price']??0));$perKm=max(0,(float)($_POST['price_per_km']??0));if($name===''){flash('Enter a vehicle name.','error');go('admin-vehicles');}try{$q=$pdo->prepare('INSERT INTO vehicles(name,vehicle_number,model,capacity,base_price,price_per_km,status) VALUES(?,?,?,?,?,?,\'Available\')');$q->execute([$name,$plate?:null,$model?:null,$capacity?:null,$base,$perKm]);flash('Vehicle added to fleet inventory.');}catch(Throwable $x){flash('Could not add this vehicle. Check the details and try again.','error');}go('admin-vehicles');}
 if($action==='update-vehicle-status'){require_role('admin');$allowed=['Available','Assigned','In Transit','Maintenance','Unavailable'];$status=$_POST['status']??'';if(!$pdo||!in_array($status,$allowed,true)){flash('Choose a valid vehicle status.','error');go('admin-vehicles');}$q=$pdo->prepare('UPDATE vehicles SET status=? WHERE id=?');$q->execute([$status,(int)($_POST['vehicle_id']??0)]);flash('Vehicle status updated.');go('admin-vehicles');}
 if($action==='remove-vehicle'){require_role('admin');if(!$pdo){flash('Database is not connected.','error');go('admin-vehicles');}$id=(int)($_POST['vehicle_id']??0);$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE vehicle_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>0){flash('This vehicle is linked to booking history and cannot be deleted. Set it to Unavailable instead.','error');go('admin-vehicles');}$q=$pdo->prepare('DELETE FROM vehicles WHERE id=?');$q->execute([$id]);flash($q->rowCount()?'Vehicle removed from fleet inventory.':'Vehicle record was not found.',$q->rowCount()?'success':'error');go('admin-vehicles');} if($action==='add-service'){require_role('admin');$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=max(0,(float)($_POST['price']??0));if(!$pdo||$name===''){flash('Enter a service name and connect the database.','error');go('admin-services');}$q=$pdo->prepare('INSERT INTO services(name,description,price,active) VALUES(?,?,?,1)');$q->execute([$name,$description,$price]);flash('Service added and made available to customers.');go('admin-services');}
 if($action==='update-service'){require_role('admin');$name=trim($_POST['name']??'');if(!$pdo||$name===''){flash('Enter a service name.','error');go('admin-services');}$q=$pdo->prepare('UPDATE services SET name=?,description=?,price=?,active=? WHERE id=?');$q->execute([$name,trim($_POST['description']??''),max(0,(float)($_POST['price']??0)),isset($_POST['active'])?1:0,(int)($_POST['service_id']??0)]);flash('Service details saved.');go('admin-services');}
 if($action==='add-payment'){require_role('admin');$methods=['Cash','Bank Transfer','Easypaisa','JazzCash'];$statuses=['Pending','Paid','Partially Paid','Refunded'];$bookingId=(int)($_POST['booking_id']??0);$method=$_POST['method']??'Cash';$status=$_POST['status']??'Pending';$amount=max(0,(float)($_POST['amount']??0));if(!$pdo||!in_array($method,$methods,true)||!in_array($status,$statuses,true)||$bookingId<1||$amount<=0){flash('Enter a valid booking, amount, method and status.','error');go('admin-payments');}$q=$pdo->prepare('INSERT INTO payments(booking_id,amount,method,status,reference,paid_at) VALUES(?,?,?,?,?,?)');$q->execute([$bookingId,$amount,$method,$status,trim($_POST['reference']??'')?:null,$status==='Paid'?date('Y-m-d H:i:s'):null]);flash('Payment record added.');go('admin-payments');}
 if($action==='update-payment'){require_role('admin');$methods=['Cash','Bank Transfer','Easypaisa','JazzCash'];$statuses=['Pending','Paid','Partially Paid','Refunded'];$method=$_POST['method']??'';$status=$_POST['status']??'';if(!$pdo||!in_array($method,$methods,true)||!in_array($status,$statuses,true)){flash('Choose a valid payment method and status.','error');go('admin-payments');}$q=$pdo->prepare("UPDATE payments SET method=?,status=?,reference=?,paid_at=IF(?='Paid',COALESCE(paid_at,NOW()),paid_at) WHERE id=?");$q->execute([$method,$status,trim($_POST['reference']??'')?:null,$status,(int)($_POST['payment_id']??0)]);flash('Payment record updated.');go('admin-payments');}
 if($action==='set-demo-review-visible'){require_role('admin');if(!$pdo){flash('Database is not connected.','error');go('admin-reviews');}$visible=(int)($_POST['visible']??0)===1?1:0;$q=$pdo->prepare('UPDATE demo_testimonials SET visible=? WHERE id=?');$q->execute([$visible,(int)($_POST['review_id']??0)]);flash($visible?'Review is visible on the homepage.':'Review hidden from the homepage.');go('admin-reviews');}
 if($action==='update-customer-review'){require_role('admin');if(!$pdo){flash('Database is not connected.','error');go('admin-reviews');}$visible=isset($_POST['visible'])?1:0;$featured=isset($_POST['featured'])?1:0;$q=$pdo->prepare('UPDATE reviews SET visible=?,featured=? WHERE id=?');$q->execute([$visible,$featured,(int)($_POST['review_id']??0)]);flash('Customer review settings saved.');go('admin-reviews');} if($action==='add-worker'){require_role('admin');if($pdo){$q=$pdo->prepare('INSERT INTO workers(name,phone,employee_id,specialization,experience,status) VALUES(?,?,?,?,?,?)');$q->execute([trim($_POST['name']??''),trim($_POST['phone']??''),trim($_POST['employee_id']??''),$_POST['specialization']??'Loading',(int)($_POST['experience']??0),'Available']);}flash('Worker added to your roster.');go('admin-workers');}
}
function booking_input():?array{$type=trim($_POST['type']??'');$pickup=trim($_POST['pickup']??'');$destination=trim($_POST['destination']??'');$date=$_POST['date']??'';$vehicle=(int)($_POST['vehicle']??0);if(!$type||!$pickup||!$destination||!$date||$date<date('Y-m-d'))return null;$items=[];foreach(($_POST['item_name']??[]) as $i=>$nm){$nm=trim($nm);$qty=max(1,(int)($_POST['item_qty'][$i]??1));if($nm)$items[]=['name'=>$nm,'qty'=>$qty,'weight'=>max(0,(float)($_POST['item_weight'][$i]??0)),'special'=>isset($_POST['item_special'][$i])?1:0];}return ['type'=>$type,'pickup'=>$pickup,'pcity'=>trim($_POST['pcity']??''),'destination'=>$destination,'dcity'=>trim($_POST['dcity']??''),'date'=>$date,'time'=>$_POST['time']??'09:00','vehicle'=>$vehicle?:null,'workers'=>max(1,(int)($_POST['workers']??2)),'notes'=>trim($_POST['notes']??''),'items'=>$items,'services'=>array_map('intval',$_POST['services']??[])];}
function estimate(array $d):int{$base=['House Shifting'=>5000,'Office Shifting'=>6500,'Room Shifting'=>2500,'Furniture Shifting'=>3000,'Vehicle Shifting'=>4500][$d['type']]??5000;$km=25;$weight=array_sum(array_map(fn($i)=>$i['weight']*$i['qty'],$d['items']));$sum=$base+$km*160+max(0,$weight-100)*9+max(0,$d['workers']-2)*1000;foreach($d['services'] as $id){$pdo=db();if($pdo){$q=$pdo->prepare('SELECT price FROM services WHERE id=?');$q->execute([$id]);$sum+=(int)($q->fetchColumn()?:0);}}return (int)$sum;}
