function dashboard_page():void{$p=db();$stats=['total'=>0,'active'=>0,'completed'=>0,'cancelled'=>0];$rows=[];if($p){$q=$p->prepare('SELECT COUNT(*) total,SUM(status NOT IN (\'Completed\',\'Cancelled\')) active,SUM(status=\'Completed\') completed,SUM(status=\'Cancelled\') cancelled FROM bookings WHERE user_id=?');$q->execute([current_user()['id']]);$r=$q->fetch();if($r)$stats=array_map(fn($x)=>(int)$x,$r);$q=$p->prepare('SELECT * FROM bookings WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$q->execute([current_user()['id']]);$rows=$q->fetchAll();}?><section class="dashboard-head"><div class="container"><span class="eyebrow">YOUR EZSHIFT SPACE</span><h1>Good to see you, <?=e(explode(' ',current_user()['name'])[0])?>.</h1><p>Your next chapter is getting closer.</p></div></section><section class="section dashboard-section"><div class="container"><div class="dash-actions"><div class="stat-cards"><div class="dash-stat"><small>TOTAL MOVES</small><b><?=$stats['total']?></b><span>Since you joined</span></div><div class="dash-stat"><small>IN PROGRESS</small><b><?=$stats['active']?></b><span>We’re on it</span></div><div class="dash-stat"><small>COMPLETED</small><b><?=$stats['completed']?></b><span>Fresh starts made</span></div><div class="dash-stat"><small>CANCELLED</small><b><?=$stats['cancelled']?></b><span>Bookings cancelled</span></div></div><a class="btn btn-primary" href="index.php?page=book">＋ Plan a new move</a></div><div class="table-card"><div class="table-heading"><div><span class="eyebrow">YOUR MOVE HISTORY</span><h2>Recent bookings</h2></div><a class="under-link" href="index.php?page=bookings">View all <span>↗</span></a></div><?php if($rows):?><div class="table-scroll"><table><thead><tr><th>MOVE ID</th><th>DATE</th><th>FROM → TO</th><th>ESTIMATE</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><b><?=e($b['booking_code'])?></b></td><td><?=e(date('M j, Y',strtotime($b['move_date'])))?></td><td><?=e($b['pickup_city']?:$b['pickup_address'])?> → <?=e($b['destination_city']?:$b['destination_address'])?></td><td>Rs. <?=number_format((float)$b['estimated_total'])?></td><td><span class="status-pill"><?=e($b['status'])?></span></td><td><a href="index.php?page=booking&id=<?=$b['id']?>">View ↗</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><span>⌂</span><h3>Your first move starts here</h3><p>Plan your move in a few simple steps and we’ll take it from there.</p><a class="btn btn-primary" href="index.php?page=book">Get a quote ↗</a></div><?php endif;?></div><div class="dashboard-shortcuts"><a href="index.php?page=profile"><span>◉</span><b>Profile</b><small>Keep your details up to date</small></a><a href="index.php?page=notifications"><span>◌</span><b>Notifications</b><small>Updates about your move</small></a><a href="index.php?page=services"><span>✧</span><b>Explore services</b><small>Find help for your move</small></a></div></div></section><?php }
function booking_list_page(string $page):void{$p=db();$rows=[];if($p){$q=$p->prepare('SELECT * FROM bookings WHERE user_id=? ORDER BY created_at DESC');$q->execute([current_user()['id']]);$rows=$q->fetchAll();}if(in_array($page,['booking','invoice','track'],true)&&isset($_GET['id'])){foreach($rows as $b)if((int)$b['id']===(int)$_GET['id']){$chosen=$b;break;}if(isset($chosen)){if($page==='invoice'){$extraRows=[];$invoiceInfo=null;$paymentInfo=['paid'=>0,'method'=>'Not recorded','statuses'=>'Pending'];if($p){try{$q=$p->prepare('SELECT s.name,s.price FROM booking_services bs JOIN services s ON s.id=bs.service_id WHERE bs.booking_id=? ORDER BY s.name');$q->execute([(int)$chosen['id']]);$extraRows=$q->fetchAll();$q=$p->prepare('SELECT * FROM invoices WHERE booking_id=? LIMIT 1');$q->execute([(int)$chosen['id']]);$invoiceInfo=$q->fetch();if(!$invoiceInfo){$invoiceNumber='EZ-I-'.preg_replace('/[^A-Z0-9-]/i','',$chosen['booking_code']);try{$q=$p->prepare('INSERT INTO invoices(booking_id,invoice_number,subtotal,discount,total) VALUES(?,?,?,0,?)');$q->execute([(int)$chosen['id'],$invoiceNumber,(float)$chosen['estimated_total'],(float)$chosen['estimated_total']]);}catch(Throwable $x){}$q=$p->prepare('SELECT * FROM invoices WHERE booking_id=? LIMIT 1');$q->execute([(int)$chosen['id']]);$invoiceInfo=$q->fetch();}$q=$p->prepare("SELECT COALESCE(SUM(CASE WHEN status IN ('Paid','Partially Paid') THEN amount ELSE 0 END),0) paid,COALESCE(GROUP_CONCAT(DISTINCT method SEPARATOR ', '),'Not recorded') method,COALESCE(GROUP_CONCAT(DISTINCT status SEPARATOR ', '),'Pending') statuses FROM payments WHERE booking_id=?");$q->execute([(int)$chosen['id']]);$paymentInfo=$q->fetch()?:$paymentInfo;}catch(Throwable $x){}}$invoiceTotal=(float)($invoiceInfo['total']??$chosen['estimated_total']);$extraTotal=array_sum(array_map(static fn($service)=>(float)$service['price'],$extraRows));$moveCharge=max(0,$invoiceTotal-$extraTotal);$adjustment=$invoiceTotal-($moveCharge+$extraTotal);$invoiceDate=strtotime($invoiceInfo['created_at']??'')?:time();?>
<section class="section"><div class="container invoice-sheet"><div class="table-heading"><div><a class="brand" href="index.php"><img class="brand-logo" src="assets/ezshift-logo.png" alt="EZShift — Moving Made Easy"></a></div><button class="btn btn-primary no-print" onclick="window.print()">Print invoice ↗</button></div><div class="invoice-banner"><span>INVOICE · <?=e($chosen['booking_code'])?></span><h1>Thank you for<br><em>choosing EZShift.</em></h1></div><div class="invoice-meta"><div><small>INVOICE NUMBER</small><b><?=e($invoiceInfo['invoice_number']??('EZ-I-'.preg_replace('/[^A-Z0-9-]/i','',$chosen['booking_code'])))?></b></div><div><small>DATE GENERATED</small><b><?=e(date('l, F j, Y',$invoiceDate))?></b></div></div><div class="detail-grid"><div><small>INVOICE TO</small><b><?=e(current_user()['name'])?><br><?=e(current_user()['email'])?></b></div><div><small>BOOKING ID</small><b><?=e($chosen['booking_code'])?></b></div><div><small>PICKUP</small><b><?=e($chosen['pickup_address'])?>, <?=e($chosen['pickup_city'])?></b></div><div><small>DESTINATION</small><b><?=e($chosen['destination_address'])?>, <?=e($chosen['destination_city'])?></b></div><div><small>SERVICE</small><b><?=e($chosen['move_type'])?></b></div><div><small>SCHEDULED</small><b><?=e(date('M j, Y',strtotime($chosen['move_date'])))?> · <?=e(substr($chosen['move_time'],0,5))?></b></div></div><div class="invoice-lines"><div class="invoice-lines-head"><span>WHAT YOU’RE PAYING FOR</span><span>AMOUNT</span></div><div class="invoice-line"><span><b><?=e($chosen['move_type'])?> · move, transport &amp; crew</b><small>Core moving estimate, distance and crew</small></span><b>Rs. <?=number_format($moveCharge)?></b></div><?php foreach($extraRows as $service):?><div class="invoice-line"><span><b><?=e($service['name'])?></b><small>Selected additional service</small></span><b>Rs. <?=number_format((float)$service['price'])?></b></div><?php endforeach;?><?php if($adjustment!=0):?><div class="invoice-line"><span><b>Booking price adjustment</b><small>Adjustment to match the confirmed booking total</small></span><b>Rs. <?=number_format($adjustment)?></b></div><?php endif;?><div class="invoice-grand"><span>Invoice total</span><b>Rs. <?=number_format($invoiceTotal)?></b></div></div><div class="invoice-payment-summary"><div><small>PAYMENT STATUS</small><b><?=e($paymentInfo['statuses'])?></b></div><div><small>PAYMENT METHOD</small><b><?=e($paymentInfo['method'])?></b></div><div><small>PAID SO FAR</small><b>Rs. <?=number_format((float)$paymentInfo['paid'])?></b></div><div><small>REMAINING</small><b>Rs. <?=number_format(max(0,$invoiceTotal-(float)$paymentInfo['paid']))?></b></div></div><p class="invoice-note">This invoice reflects the booking amount and selected add-on services currently recorded for your move.</p></div></section><?php return;}?><section class="page-hero compact"><div class="container"><span class="eyebrow">BOOKING DETAILS</span><h1><?=e($chosen['booking_code'])?></h1><p>Your move, from the first plan to the final hand-off.</p></div></section><section class="section"><div class="container"><div class="table-card detail-card"><div class="table-heading"><div><span class="eyebrow">CURRENT STATUS</span><h2><?=e($chosen['status'])?></h2></div><a class="btn btn-outline" href="index.php?page=invoice&id=<?=$chosen['id']?>">View invoice ↗</a></div><div class="progress-track"><?php $steps=['Pending','Confirmed','Workers Assigned','Vehicle Assigned','On the Way','Loading','In Transit','Unloading','Completed'];$pos=array_search($chosen['status'],$steps);foreach($steps as $i=>$s):?><div class="progress-step <?=$pos!==false&&$i<=$pos?'done':''?>"><i></i><span><?=e($s)?></span></div><?php endforeach;?></div><div class="detail-grid"><div><small>PICKUP</small><b><?=e($chosen['pickup_address'])?>, <?=e($chosen['pickup_city'])?></b></div><div><small>DESTINATION</small><b><?=e($chosen['destination_address'])?>, <?=e($chosen['destination_city'])?></b></div><div><small>MOVING DATE</small><b><?=e(date('M j, Y',strtotime($chosen['move_date'])))?> · <?=e(substr($chosen['move_time'],0,5))?></b></div><div><small>SERVICE</small><b><?=e($chosen['move_type'])?></b></div></div><div class="invoice-total"><span>Estimated total</span><b>Rs. <?=number_format((float)$chosen['estimated_total'])?></b></div></div></div></section><?php return;}}?><section class="page-hero compact"><div class="container"><span class="eyebrow">YOUR MOVE HISTORY</span><h1>Every move,<br><em>in one place.</em></h1></div></section><section class="section"><div class="container table-card"><div class="table-heading"><h2>My bookings</h2><input class="table-search" placeholder="Search booking or city..." data-table-search></div><div class="table-scroll"><table><thead><tr><th>MOVE ID</th><th>DATE</th><th>FROM → TO</th><th>TYPE</th><th>ESTIMATE</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><b><?=e($b['booking_code'])?></b></td><td><?=e(date('M j, Y',strtotime($b['move_date'])))?></td><td><?=e($b['pickup_city'])?> → <?=e($b['destination_city'])?></td><td><?=e($b['move_type'])?></td><td>Rs. <?=number_format((float)$b['estimated_total'])?></td><td><span class="status-pill"><?=e($b['status'])?></span></td><td><a href="index.php?page=booking&id=<?=$b['id']?>">View ↗</a></td></tr><?php endforeach;?></tbody></table></div></div></section><?php }
