function admin_page(string $page):void{$p=db();$counts=['customers'=>0,'bookings'=>0,'pending'=>0,'active'=>0,'completed'=>0,'workers'=>0,'vehicles'=>0,'revenue'=>0];if($p){foreach(['customers'=>'SELECT COUNT(*) FROM users WHERE role=\'customer\'','bookings'=>'SELECT COUNT(*) FROM bookings','pending'=>'SELECT COUNT(*) FROM bookings WHERE status=\'Pending\'','active'=>'SELECT COUNT(*) FROM bookings WHERE status NOT IN (\'Pending\',\'Completed\',\'Cancelled\')','completed'=>'SELECT COUNT(*) FROM bookings WHERE status=\'Completed\'','workers'=>'SELECT COUNT(*) FROM workers WHERE status=\'Available\'','vehicles'=>'SELECT COUNT(*) FROM vehicles WHERE status=\'Available\'','revenue'=>'SELECT COALESCE(SUM(amount),0) FROM payments WHERE status=\'Paid\''] as $k=>$sql){try{$counts[$k]=(float)$p->query($sql)->fetchColumn();}catch(Throwable $x){}}}$rows=[];$pendingRows=[];if($p&&in_array($page,['admin','admin-bookings'],true))$rows=$p->query('SELECT b.*,u.name customer FROM bookings b JOIN users u ON u.id=b.user_id ORDER BY b.created_at DESC LIMIT 100')->fetchAll();if($p&&$page==='admin')$pendingRows=$p->query("SELECT b.*,u.name customer FROM bookings b JOIN users u ON u.id=b.user_id WHERE b.status='Pending' ORDER BY b.created_at ASC LIMIT 30")->fetchAll();$heading=['admin'=>'Operations overview','admin-bookings'=>'Bookings','admin-customers'=>'Customers','admin-workers'=>'Your crew','admin-vehicles'=>'Your fleet','admin-services'=>'Services','admin-payments'=>'Payments','admin-reviews'=>'Reviews'][$page]??'Admin';?><section class="dashboard-head"><div class="container admin-head"><div><span class="eyebrow">EZSHIFT OPERATIONS</span><h1><?=e($heading)?></h1><p>Good morning, <?=e(explode(' ',current_user()['name'])[0])?>. Here’s the day at a glance.</p></div><a class="btn btn-primary" href="index.php?page=admin-bookings">View bookings ↗</a></div></section><section class="section dashboard-section"><div class="container"><div class="admin-nav"><a class="<?=$page==='admin'?'active':''?>" href="index.php?page=admin">Overview</a><a class="<?=$page==='admin-bookings'?'active':''?>" href="index.php?page=admin-bookings">Bookings</a><a class="<?=$page==='admin-customers'?'active':''?>" href="index.php?page=admin-customers">Customers</a><a class="<?=$page==='admin-workers'?'active':''?>" href="index.php?page=admin-workers">Workers</a><a class="<?=$page==='admin-vehicles'?'active':''?>" href="index.php?page=admin-vehicles">Vehicles</a><a class="<?=$page==='admin-services'?'active':''?>" href="index.php?page=admin-services">Services</a><a class="<?=$page==='admin-payments'?'active':''?>" href="index.php?page=admin-payments">Payments</a><a class="<?=$page==='admin-reviews'?'active':''?>" href="index.php?page=admin-reviews">Reviews</a></div><div class="admin-stats"><?php foreach(['customers'=>'Customers','bookings'=>'Total bookings','pending'=>'Pending requests','active'=>'Active moves','completed'=>'Completed','workers'=>'Available workers','vehicles'=>'Available vehicles'] as $k=>$label):?><div class="dash-stat"><small><?=e(strtoupper($label))?></small><b><?=number_format($counts[$k])?></b><span>Live overview</span></div><?php endforeach;?><div class="dash-stat"><small>PAID REVENUE</small><b>Rs. <?=number_format($counts['revenue'])?></b><span>Payments received</span></div></div><?php if($page==='admin'):?><div class="table-card pending-requests"><div class="table-heading"><div><span class="eyebrow">NEW CUSTOMER REQUESTS</span><h2>Awaiting your confirmation</h2></div><span class="pending-count"><?=count($pendingRows)?> pending</span></div><?php if($pendingRows):?><div class="table-scroll"><table><thead><tr><th>REQUEST</th><th>CUSTOMER</th><th>ROUTE</th><th>MOVE DATE</th><th>ESTIMATE</th><th>CONFIRM</th></tr></thead><tbody><?php foreach($pendingRows as $b):?><tr><td><b><?=e($b['booking_code'])?></b></td><td><?=e($b['customer'])?></td><td><?=e($b['pickup_city']?:$b['pickup_address'])?> → <?=e($b['destination_city']?:$b['destination_address'])?></td><td><?=e(date('M j, Y',strtotime($b['move_date'])))?></td><td>Rs. <?=number_format((float)$b['estimated_total'])?></td><td><form class="inline-form confirm-request" method="post"><input type="hidden" name="action" value="update-status"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><input type="hidden" name="status" value="Confirmed"><input type="hidden" name="return_to" value="admin"><button class="btn btn-primary btn-small">Confirm</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><span>✓</span><h3>No requests waiting</h3><p>New customer shift requests will appear here.</p></div><?php endif;?></div><?php endif;?><?php if(in_array($page,['admin','admin-bookings'],true)):?><div class="table-card"><div class="table-heading"><div><span class="eyebrow">WHAT NEEDS YOUR ATTENTION</span><h2>Latest bookings</h2></div><input class="table-search" placeholder="Search booking or customer..." data-table-search></div><div class="table-scroll"><table><thead><tr><th>BOOKING ID</th><th>CUSTOMER</th><th>PICKUP → DESTINATION</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><b><?=e($b['booking_code'])?></b></td><td><?=e($b['customer'])?></td><td><?=e($b['pickup_city'])?> → <?=e($b['destination_city'])?></td><td><?=e(date('M j',strtotime($b['move_date'])))?></td><td>Rs. <?=number_format((float)$b['estimated_total'])?></td><td><span class="status-pill"><?=e($b['status'])?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="action" value="update-status"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><select name="status" aria-label="Change status"><option><?=e($b['status'])?></option><?php foreach(['Confirmed','Workers Assigned','Vehicle Assigned','On the Way','Loading','In Transit','Unloading','Completed','Cancelled'] as $s)if($s!==$b['status']):?><option><?=e($s)?></option><?php endif;?></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php elseif($page==='admin-workers'):?><div class="table-card"><div class="table-heading"><div><span class="eyebrow">YOUR PEOPLE</span><h2>Worker roster</h2></div></div><form method="post" class="worker-add"><input type="hidden" name="action" value="add-worker"><input name="name" required placeholder="Worker name"><input name="phone" placeholder="Phone"><input name="employee_id" placeholder="Employee ID"><select name="specialization"><option>Loading</option><option>Packing</option><option>Furniture handling</option><option>Fragile items</option><option>Driving</option></select><input type="number" name="experience" placeholder="Years exp."><button class="btn btn-primary">＋ Add worker</button></form><?php $workers=$p?$p->query('SELECT * FROM workers ORDER BY id DESC')->fetchAll():[];?><div class="table-scroll"><table><thead><tr><th>NAME</th><th>EMPLOYEE ID</th><th>PHONE</th><th>SKILL</th><th>EXPERIENCE</th><th>STATUS</th></tr></thead><tbody><?php foreach($workers as $w):?><tr><td><?=e($w['name'])?></td><td><?=e($w['employee_id'])?></td><td><?=e($w['phone'])?></td><td><?=e($w['specialization'])?></td><td><?=e($w['experience'])?> yrs</td><td><span class="status-pill"><?=e($w['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php elseif($page==='admin-vehicles'):?><?php $fleetRows=[];$fleetTotals=['total'=>0,'available'=>0,'working'=>0,'inactive'=>0];if($p){$fleetRows=$p->query('SELECT * FROM vehicles ORDER BY name ASC,id ASC')->fetchAll();$fleetTotals=$p->query("SELECT COUNT(*) total,COALESCE(SUM(status='Available'),0) available,COALESCE(SUM(status IN ('Assigned','In Transit')),0) working,COALESCE(SUM(status IN ('Maintenance','Unavailable')),0) inactive FROM vehicles")->fetch()?:$fleetTotals;}?><div class="fleet-inventory-stats"><div><small>TOTAL VEHICLES</small><b><?=number_format((int)$fleetTotals['total'])?></b></div><div><small>AVAILABLE</small><b><?=number_format((int)$fleetTotals['available'])?></b></div><div><small>ASSIGNED / IN TRANSIT</small><b><?=number_format((int)$fleetTotals['working'])?></b></div><div><small>MAINTENANCE / UNAVAILABLE</small><b><?=number_format((int)$fleetTotals['inactive'])?></b></div></div><div class="table-card fleet-inventory"><div class="table-heading"><div><span class="eyebrow">FLEET INVENTORY</span><h2>Vehicles you own</h2><p>Each row is one vehicle. Add units to increase your fleet count or remove an unused vehicle.</p></div></div><form method="post" class="vehicle-add"><input type="hidden" name="action" value="add-vehicle"><label>Vehicle name<input name="name" required maxlength="100" placeholder="e.g. Suzuki Ravi"></label><label>Registration number<input name="vehicle_number" maxlength="30" placeholder="e.g. ABC-1234"></label><label>Model / year<input name="model" maxlength="80" placeholder="e.g. 2024"></label><label>Capacity<input name="capacity" maxlength="80" placeholder="e.g. Small move · 350 kg"></label><label>Base price<input type="number" name="base_price" min="0" step="100" value="0"></label><label>Price / km<input type="number" name="price_per_km" min="0" step="10" value="0"></label><button class="btn btn-primary">＋ Add vehicle</button></form><?php if($fleetRows):?><div class="table-scroll"><table><thead><tr><th>VEHICLE</th><th>REGISTRATION</th><th>MODEL / CAPACITY</th><th>BASE · PER KM</th><th>STATUS</th><th>REMOVE</th></tr></thead><tbody><?php foreach($fleetRows as $v):?><tr><td><b><?=e($v['name'])?></b></td><td><?=e($v['vehicle_number']?:'—')?></td><td><?=e(trim(($v['model']?:'').(($v['model']&&$v['capacity'])?' · ':'').($v['capacity']?:''))?:'—')?></td><td>Rs. <?=number_format((float)$v['base_price'])?> · Rs. <?=number_format((float)$v['price_per_km'])?>/km</td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="update-vehicle-status"><input type="hidden" name="vehicle_id" value="<?=$v['id']?>"><select name="status" aria-label="<?=e($v['name'])?> status"><?php foreach(['Available','Assigned','In Transit','Maintenance','Unavailable'] as $state):?><option value="<?=e($state)?>" <?=$v['status']===$state?'selected':''?>><?=e($state)?></option><?php endforeach;?></select><button>Save</button></form></td><td><form method="post" onsubmit="return confirm('Remove this vehicle from the fleet inventory?')"><input type="hidden" name="action" value="remove-vehicle"><input type="hidden" name="vehicle_id" value="<?=$v['id']?>"><button class="fleet-remove" aria-label="Remove <?=e($v['name'])?>">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><span>＋</span><h3>No vehicles in inventory</h3><p>Add your first vehicle using the form above.</p></div><?php endif;?></div><?php elseif($page==='admin-services'):?><?php $serviceAdminRows=$p?$p->query('SELECT * FROM services ORDER BY active DESC,name ASC')->fetchAll():[];?><div class="table-card admin-management"><div class="table-heading"><div><span class="eyebrow">CUSTOMER OFFERINGS</span><h2>Manage services</h2><p>Changes to active services and prices appear in customer booking forms.</p></div></div><form method="post" class="service-add"><input type="hidden" name="action" value="add-service"><label>Service name<input name="name" required maxlength="120" placeholder="e.g. Piano moving"></label><label>Description<input name="description" maxlength="500" placeholder="What customers can expect"></label><label>Starting price (Rs.)<input type="number" name="price" min="0" step="100" value="0"></label><button class="btn btn-primary">＋ Add service</button></form><?php if($serviceAdminRows):?><div class="table-scroll"><table><thead><tr><th>SERVICE</th><th>DESCRIPTION</th><th>PRICE (RS.)</th><th>ACTIVE</th><th>SAVE</th></tr></thead><tbody><?php foreach($serviceAdminRows as $sv):?><tr><td><input form="service-form-<?=$sv['id']?>" class="service-cell-input" name="name" required value="<?=e($sv['name'])?>" aria-label="Service name"></td><td><input form="service-form-<?=$sv['id']?>" class="service-cell-input" name="description" value="<?=e($sv['description'])?>" aria-label="Description"></td><td><input form="service-form-<?=$sv['id']?>" class="service-cell-input service-price-input" type="number" min="0" step="100" name="price" value="<?=e($sv['price'])?>" aria-label="Price in rupees"></td><td><label class="service-active"><input form="service-form-<?=$sv['id']?>" type="checkbox" name="active" value="1" <?=$sv['active']?'checked':''?>> Active</label></td><td><form id="service-form-<?=$sv['id']?>" method="post"><input type="hidden" name="action" value="update-service"><input type="hidden" name="service_id" value="<?=$sv['id']?>"><button class="btn btn-outline btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No services yet</h3><p>Add the first service above.</p></div><?php endif;?></div>
<?php elseif($page==='admin-payments'):?><?php $paymentRows=$p?$p->query('SELECT p.*,b.booking_code,u.name customer FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN users u ON u.id=b.user_id ORDER BY p.id DESC')->fetchAll():[];$paymentBookings=$p?$p->query('SELECT b.id,b.booking_code,u.name customer,b.estimated_total FROM bookings b JOIN users u ON u.id=b.user_id ORDER BY b.created_at DESC')->fetchAll():[];$paymentTotals=['paid'=>0,'pending'=>0,'refunded'=>0];if($p){$paymentTotals=$p->query("SELECT COALESCE(SUM(CASE WHEN status IN ('Paid','Partially Paid') THEN amount ELSE 0 END),0) paid,COALESCE(SUM(status='Pending'),0) pending,COALESCE(SUM(status='Refunded'),0) refunded FROM payments")->fetch()?:$paymentTotals;}?><div class="fleet-inventory-stats payment-stats"><div><small>PAID / PARTIAL AMOUNT</small><b>Rs. <?=number_format((float)$paymentTotals['paid'])?></b></div><div><small>PENDING RECORDS</small><b><?=number_format((int)$paymentTotals['pending'])?></b></div><div><small>REFUNDED AMOUNT</small><b>Rs. <?=number_format((float)$paymentTotals['refunded'])?></b></div></div><div class="table-card admin-management"><div class="table-heading"><div><span class="eyebrow">PAYMENT RECORDS</span><h2>Payments</h2><p>Record payments against a booking and keep each transaction status up to date.</p></div><input class="table-search" placeholder="Search payment, customer, booking..." data-table-search></div><form method="post" class="payment-add"><input type="hidden" name="action" value="add-payment"><label>Booking<select name="booking_id" required><?php foreach($paymentBookings as $pb):?><option value="<?=$pb['id']?>"><?=e($pb['booking_code'])?> · <?=e($pb['customer'])?></option><?php endforeach;?></select></label><label>Amount (Rs.)<input type="number" name="amount" min="1" step="100" required placeholder="0"></label><label>Method<select name="method"><option>Cash</option><option>Bank Transfer</option><option>Easypaisa</option><option>JazzCash</option></select></label><label>Status<select name="status"><option>Pending</option><option>Paid</option><option>Partially Paid</option><option>Refunded</option></select></label><label>Reference<input name="reference" maxlength="100" placeholder="Transaction / receipt ID"></label><button class="btn btn-primary">＋ Add payment</button></form><?php if($paymentRows):?><div class="table-scroll"><table><thead><tr><th>PAYMENT / BOOKING</th><th>CUSTOMER</th><th>AMOUNT</th><th>METHOD</th><th>STATUS</th><th>REFERENCE</th><th>SAVE</th></tr></thead><tbody><?php foreach($paymentRows as $pay):?><tr><td><b>#<?=$pay['id']?> · <?=e($pay['booking_code'])?></b></td><td><?=e($pay['customer'])?></td><td>Rs. <?=number_format((float)$pay['amount'])?></td><td colspan="4"><form method="post" class="payment-edit"><input type="hidden" name="action" value="update-payment"><input type="hidden" name="payment_id" value="<?=$pay['id']?>"><select name="method"><option <?= $pay['method']==='Cash'?'selected':''?>>Cash</option><option <?= $pay['method']==='Bank Transfer'?'selected':''?>>Bank Transfer</option><option <?= $pay['method']==='Easypaisa'?'selected':''?>>Easypaisa</option><option <?= $pay['method']==='JazzCash'?'selected':''?>>JazzCash</option></select><select name="status"><option <?= $pay['status']==='Pending'?'selected':''?>>Pending</option><option <?= $pay['status']==='Paid'?'selected':''?>>Paid</option><option <?= $pay['status']==='Partially Paid'?'selected':''?>>Partially Paid</option><option <?= $pay['status']==='Refunded'?'selected':''?>>Refunded</option></select><input name="reference" value="<?=e($pay['reference']??'')?>" placeholder="Reference"><button class="btn btn-outline btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><span>Rs</span><h3>No payment records yet</h3><p>Use the form above to record a customer payment.</p></div><?php endif;?></div>
<?php elseif($page==='admin-reviews'):?><?php $demoReviewRows=$p?$p->query('SELECT * FROM demo_testimonials ORDER BY id ASC')->fetchAll():[];$customerReviewRows=$p?$p->query('SELECT r.*,u.name customer,b.booking_code FROM reviews r JOIN users u ON u.id=r.user_id JOIN bookings b ON b.id=r.booking_id ORDER BY r.created_at DESC')->fetchAll():[];?><div class="table-card admin-management review-admin-card"><div class="table-heading"><div><span class="eyebrow">HOMEPAGE REVIEWS</span><h2><?=count($demoReviewRows)?> reviews from the site carousel</h2><p>Hide a review to remove it from the homepage, or show it again later.</p></div><input class="table-search" placeholder="Search name, city or review..." data-table-search></div><?php if($demoReviewRows):?><div class="table-scroll"><table><thead><tr><th>REVIEWER</th><th>MOVE / CITY</th><th>RATING</th><th>REVIEW</th><th>VISIBILITY</th><th>ACTION</th></tr></thead><tbody><?php foreach($demoReviewRows as $dr):?><tr><td><b><?=e($dr['reviewer_name'])?></b></td><td><?=e($dr['move_type'])?><small class="table-subline"><?=e($dr['city'])?></small></td><td class="admin-stars"><?=str_repeat('★',(int)$dr['rating'])?></td><td class="review-copy-cell"><?=e($dr['review'])?></td><td><span class="status-pill"><?=$dr['visible']?'Visible':'Hidden'?></span></td><td><form method="post"><input type="hidden" name="action" value="set-demo-review-visible"><input type="hidden" name="review_id" value="<?=$dr['id']?>"><input type="hidden" name="visible" value="<?=$dr['visible']?0:1?>"><button class="btn btn-outline btn-small"><?=$dr['visible']?'Hide':'Show'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No homepage reviews found</h3><p>The demo_testimonials table is missing or empty.</p></div><?php endif;?></div><div class="table-card admin-management review-admin-card"><div class="table-heading"><div><span class="eyebrow">CUSTOMER SUBMISSIONS</span><h2>Submitted reviews</h2><p>Feature or hide reviews customers submitted after completed moves.</p></div></div><?php if($customerReviewRows):?><div class="table-scroll"><table><thead><tr><th>BOOKING</th><th>CUSTOMER</th><th>RATING</th><th>REVIEW</th><th>SETTINGS</th></tr></thead><tbody><?php foreach($customerReviewRows as $cr):?><tr><td><?=e($cr['booking_code'])?></td><td><?=e($cr['customer'])?></td><td class="admin-stars"><?=str_repeat('★',(int)$cr['rating'])?></td><td class="review-copy-cell"><?=e($cr['review'])?></td><td><form method="post" class="review-flags"><input type="hidden" name="action" value="update-customer-review"><input type="hidden" name="review_id" value="<?=$cr['id']?>"><label><input type="checkbox" name="visible" value="1" <?=$cr['visible']?'checked':''?>> Visible</label><label><input type="checkbox" name="featured" value="1" <?=$cr['featured']?'checked':''?>> Featured</label><button class="btn btn-outline btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><span>✧</span><h3>No customer submissions yet</h3><p>Reviews customers submit after completed moves will appear here.</p></div><?php endif;?></div><?php else:?><div class="table-card"><div class="empty-state"><span>✧</span><h3><?=e($heading)?> at a glance</h3><p>Connect the EZShift database to review and manage these records.</p></div></div><?php endif;?></div></section><?php }
